            return (apis->virtual_router_api && apis->virtual_router_api->get_virtual_router_attribute)
                ? apis->virtual_router_api->get_virtual_router_attribute(meta_key->objectkey.key.object_id, attr_count, attr_list)
                : SAI_STATUS_NOT_IMPLEMENTED;
        case SAI_OBJECT_TYPE_NEXT_HOP:
