            case SAI_SWITCH_ATTR_TAM_EVENT_NOTIFY:
                sn->on_tam_event = (sai_tam_event_notification_fn)attrs[idx].value.ptr;
                break;
            case SAI_SWITCH_ATTR_IPSEC_SA_STATUS_CHANGE_NOTIFY:
                sn->on_ipsec_sa_status_change = (sai_ipsec_sa_status_change_notification_fn)attrs[idx].value.ptr;
                break;
            case SAI_SWITCH_ATTR_NAT_EVENT_NOTIFY:
                sn->on_nat_event = (sai_nat_event_notification_fn)attrs[idx].value.ptr;
                break;
            case SAI_SWITCH_ATTR_SWITCH_ASIC_SDK_HEALTH_EVENT_NOTIFY:
